# Since I can't import the library directly, I'll implement a simplified version
# of the approach to find patterns

inputs = ['ie', 'wegyff', 'uwzygw', 'aadxkz', 'cib']
outputs = ['ie', 'wewyff', 'uwfyww', 'aadfkkf', 'cib']

# Let me manually check for character-level changes
changed_pairs = []
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        changed_pairs.append((i, inp, outp))

print("Changed pairs:")
for idx, inp, outp in changed_pairs:
    print(f"  {idx}: '{inp}' -> '{outp}'")

# Let's look at the character-by-character differences
print("\nCharacter-by-character differences:")
for idx, inp, outp in changed_pairs:
    print(f"  {idx}: '{inp}' -> '{outp}'")
    min_len = min(len(inp), len(outp))
    for i in range(min_len):
        if inp[i] != outp[i]:
            print(f"    Position {i}: '{inp[i]}' -> '{outp[i]}'")
    if len(inp) != len(outp):
        print(f"    Length change: {len(inp)} -> {len(outp)}")

